package wgmodern;
import net.minecraft.client.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.core.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;
public class TerraformRenderer implements BlockEntityRenderer<Terraformer.Tile> {
 static final ResourceLocation MODEL=new ResourceLocation("witchinggadgets","models/terraformer.obj"),TEXTURE=new ResourceLocation("witchinggadgets","textures/models/terraformer.png");
 public TerraformRenderer(BlockEntityRendererProvider.Context c){}
 @Override public void render(Terraformer.Tile tile,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){draw(pose,buffers,light,overlay,tile.required()==null?0xffffff:tile.required().color(),false,null,tile.getLevel(),tile.getBlockPos(),partial);}
 public static void draw(PoseStack pose,MultiBufferSource buffers,int light,int overlay,int color,boolean focus,Terraformer.Focus def,Level level,BlockPos pos,float partial){pose.pushPose();pose.translate(.5,focus?-1:0,.5);var model=LegacyObj.get(MODEL);var out=buffers.getBuffer(RenderType.entityCutoutNoCull(TEXTURE));model.draw(focus?"focus_03":"main_01",pose,out,light,overlay,0xffffff,1);model.draw(focus?"focus_crystal_04":"crystals_02",pose,out,light,overlay,color,1);if(focus&&level!=null&&def!=null){var displayed=def.displayedBlock(level,pos);if(!displayed.isEmpty()){float rotation=((Minecraft.getInstance().player.tickCount%40)+partial)/40f*360;pose.translate(0,1.3125,0);pose.scale(.25f,.25f,.25f);pose.mulPose(Axis.YP.rotationDegrees(rotation));pose.mulPose(Axis.ZP.rotationDegrees(rotation));Minecraft.getInstance().getItemRenderer().renderStatic(displayed,ItemDisplayContext.NONE,light,overlay,pose,buffers,level,0);}}pose.popPose();}
 public static class FocusRenderer implements BlockEntityRenderer<Terraformer.FocusTile>{public FocusRenderer(BlockEntityRendererProvider.Context c){}@Override public void render(Terraformer.FocusTile tile,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var focus=(Terraformer.Focus)tile.getBlockState().getBlock();draw(pose,buffers,light,overlay,focus.requiredAspect(tile.getLevel(),tile.getBlockPos()).color(),true,focus,tile.getLevel(),tile.getBlockPos(),partial);}}
 public static class ItemRenderer extends BlockEntityWithoutLevelRenderer {private static ItemRenderer instance;public static ItemRenderer instance(){if(instance==null)instance=new ItemRenderer();return instance;}public ItemRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}@Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var block=((BlockItem)stack.getItem()).getBlock();var focus=block instanceof Terraformer.Focus f?f:null;draw(pose,buffers,light,overlay,focus==null?0xffffff:focus.requiredAspect(null,null).color(),focus!=null,focus,null,null,0);}}
 public static void vent(BlockPos p,int color){var level=Minecraft.getInstance().level;if(level==null)return;for(int j=0;j<4;j++)for(var f:Direction.Plane.HORIZONTAL)tc4revival.client.EssentiaVentParticles.emit(level,p.getX()+.5+.6875*f.getStepX(),p.getY()+.875,p.getZ()+.5+.6875*f.getStepZ(),.1875,.25,.1875,color,2);}
}
